 * Pure workload calculator for the "Resource Chart" additional feature.
 *
 * Shows how loaded each team member is over time so a PM can spot
 * overallocation and idle capacity. It only reports — it never moves tasks
 * (no resource leveling).
 *
 * Same rules as the scheduling engine (D-05): no Eloquent, no facades, no
 * HTTP — deterministic input/output only.
 *
 * Rules implemented (Resource Chart part 1):
 *  - Parent tasks are never counted; only leaf tasks.
 *  - A task assigned to several members counts fully for each member.
 *  - load(day) = sum of the allocation percent of active assigned tasks.
 *  - capacity(day) = 100 on working days; 0 on weekends, holidays and the
 *    member's leave days.
 *  - overallocated = load > capacity (therefore a task spanning a weekend or
 *    holiday — where capacity is 0 — is reported on those days too: work
 *    sitting on a non-working day is a conflict the PM should see).
 *  - leaveConflict = member is on leave that day AND an assigned task is
 *    active that day.
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:19:"App\Domain\Workload";s:4:"uses";a:3:{s:15:"workingcalendar";s:37:"App\Domain\Scheduling\WorkingCalendar";s:17:"datetimeimmutable";s:17:"DateTimeImmutable";s:24:"invalidargumentexception";s:24:"InvalidArgumentException";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:1;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:1:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:9:"calculate";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":2:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:199:"/**
